    "/api/alarmsQuery/find": {
        parameters: {
            query?: never;
            header?: never;
            path?: never;
            cookie?: never;
        };
        get?: never;
        put?: never;
        /**
         * Find Alarms by Query
         * @description This method description defines how Alarm Data Query extends the Entity Data Query. See method 'Find Entity Data by Query' first to get the info about 'Entity Data Query'.
         *
         *      The platform will first search the entities that match the entity and key filters. Then, the platform will use 'Alarm Page Link' to filter the alarms related to those entities. Finally, platform fetch the properties of alarm that are defined in the **'alarmFields'** and combine them with the other entity, attribute and latest time series fields to return the result.
         *
         *      See example of the alarm query below. The query will search first 100 active alarms with type 'Temperature Alarm' or 'Fire Alarm' for any device with current temperature > 0. The query will return combination of the entity fields: name of the device, device model and latest temperature reading and alarms fields: createdTime, type, severity and status:
         *
         *     ```json
         *     {
         *       "entityFilter": {
         *         "type": "entityType",
         *         "resolveMultiple": true,
         *         "entityType": "DEVICE"
         *       },
         *       "pageLink": {
         *         "page": 0,
         *         "pageSize": 100,
         *         "textSearch": null,
         *         "searchPropagatedAlarms": false,
         *         "statusList": [
         *           "ACTIVE"
         *         ],
         *         "severityList": [
         *           "CRITICAL",
         *           "MAJOR"
         *         ],
         *         "typeList": [
         *           "Temperature Alarm",
         *           "Fire Alarm"
         *         ],
         *         "sortOrder": {
         *           "key": {
         *             "key": "createdTime",
         *             "type": "ALARM_FIELD"
         *           },
         *           "direction": "DESC"
         *         },
         *         "timeWindow": 86400000
         *       },
         *       "keyFilters": [
         *         {
         *           "key": {
         *             "type": "TIME_SERIES",
         *             "key": "temperature"
         *           },
         *           "valueType": "NUMERIC",
         *           "predicate": {
         *             "operation": "GREATER",
         *             "value": {
         *               "defaultValue": 0,
         *               "dynamicValue": null
         *             },
         *             "type": "NUMERIC"
         *           }
         *         }
         *       ],
         *       "alarmFields": [
         *         {
         *           "type": "ALARM_FIELD",
         *           "key": "createdTime"
         *         },
         *         {
         *           "type": "ALARM_FIELD",
         *           "key": "type"
         *         },
         *         {
         *           "type": "ALARM_FIELD",
         *           "key": "severity"
         *         },
         *         {
         *           "type": "ALARM_FIELD",
         *           "key": "status"
         *         }
         *       ],
         *       "entityFields": [
         *         {
         *           "type": "ENTITY_FIELD",
         *           "key": "name"
         *         }
         *       ],
         *       "latestValues": [
         *         {
         *           "type": "ATTRIBUTE",
         *           "key": "model"
         *         },
         *         {
         *           "type": "TIME_SERIES",
         *           "key": "temperature"
         *         }
         *       ]
         *     }
         *     ```
         */
        post: operations["findAlarmDataByQuery"];
        delete?: never;
        options?: never;
        head?: never;
        patch?: never;
        trace?: never;
    };
